import { useQuery } from '@tanstack/react-query';
import { getFeaturedProducts } from '@/api/product';
import Header from '@/components/Header';
import ProductCard from '@/components/product/ProductCard';

interface Product {
  id: number;
  name: string;
  price: number;
  thumbnail: string;
  category?: { name: string };
}

export default function Home() {
  const { data, isLoading, error } = useQuery({
    queryKey: ['featured-products'],
    queryFn: getFeaturedProducts,
  });

  const products = data?.items || [];

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white">
        <div className="max-w-7xl mx-auto px-8 py-8">
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="h-48 bg-gray-200 rounded-lg mb-4" />
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-4 bg-gray-200 rounded w-1/2" />
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      <Header />

      {/* Hero Banner */}
      <div className="h-72 bg-gradient-to-r from-blue-500 to-purple-600 flex items-center justify-center">
        <h1 className="text-4xl font-bold text-white">Welcome to INTERNSHOP</h1>
      </div>

      {/* Featured Products */}
      <div className="max-w-7xl mx-auto px-8 py-8">
        <h2 className="text-xl font-bold mb-6">Sản phẩm nổi bật</h2>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {products.map((product: Product) => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
        {products.length === 0 && (
          <div className="text-center py-12 text-gray-500">
            Chưa có sản phẩm nào
          </div>
        )}
      </div>
    </div>
  );
}
